cd /workspace && python3 -c "
import sqlite3, json
conn = sqlite3.connect('world.db')
cur = conn.cursor()

# Get all flights from JFK on Sep 8 and Sep 10
for date in ['2026-09-08', '2026-09-10']:
    print(f'=== Searching JFK -> ??? -> SFO on {date} ===')
    print()

    # Leg 1: Flights from JFK on this date
    cur.execute('SELECT flight_id, origin, destination, departure_time, arrival_time, cabin_prices_json, dates_json FROM flights WHERE origin=\"JFK\"')
    jfk_flights = []
    for f in cur.fetchall():
        dates = json.loads(f[6]) if f[6] else {}
        if date in dates:
            prices = json.loads(f[5]) if f[5] else {}
            date_info = dates[date]
            jfk_flights.append({
                'id': f[0], 'origin': f[1], 'dest': f[2],
                'dep': f[3], 'arr': f[4], 'prices': prices,
                'seats': date_info.get('available_seats', {}),
                'status': date_info.get('status', 'unknown')
            })

    for leg1 in jfk_flights:
        if leg1['status'] != 'available':
            continue
        connecting = leg1['dest']

        # Leg 2: Flights from connecting city to SFO (same date or next day)
        for date2 in [date, f'2026-09-{int(date[-2:])+1:02d}']:
            cur.execute('SELECT flight_id, origin, destination, departure_time, arrival_time, cabin_prices_json, dates_json FROM flights WHERE origin=? AND destination=\"SFO\"', (connecting,))
            for f2 in cur.fetchall():
                dates2 = json.loads(f2[6]) if f2[6] else {}
                if date2 in dates2:
                    date2_info = dates2[date2]
                    if date2_info.get('status') != 'available':
                        continue
                    prices2 = json.loads(f2[5]) if f2[5] else {}
                    seats2 = date2_info.get('available_seats', {})

                    print(f'  OPTION FOUND via {connecting}:')
                    print(f'    Leg 1: {leg1[\"id\"]} | {leg1[\"origin\"]} -> {leg1[\"dest\"]} | Dep: {leg1[\"dep\"]} | Arr: {leg1[\"arr\"]}')
                    print(f'      Prices: {leg1[\"prices\"]}')
                    print(f'      Seats:  {leg1[\"seats\"]}')
                    print(f'    Leg 2: {f2[0]} | {f2[1]} -> {f2[2]} | Dep: {f2[3]} | Arr: {f2[4]} (on {date2})')
                    print(f'      Prices: {prices2}')
                    print(f'      Seats:  {seats2}')

                    # Combined prices
                    for cabin in ['basic_economy', 'economy', 'business']:
                        p1 = leg1['prices'].get(cabin)
                        p2 = prices2.get(cabin)
                        if p1 and p2:
                            print(f'      -> Combined {cabin}: \${p1 + p2}')
                    print()

    if not jfk_flights:
        print(f'  No flights from JFK on {date}')
    print()
"

